'use strict';
// Version-independent MCP entry. Harness configs point at this file instead of
// the versioned extension folder, so an upgrade does not leave them on an old copy.
const fs = require('node:fs');
const path = require('node:path');
const PREFIX = 'local.devin-fusion-byok-';
const FILE = 'fusion-mcp.cjs';

function launcherSource({ extensionsDir, fallback }) {
  return `#!/usr/bin/env node
'use strict';
// Generated by Devin Fusion BYOK. Starts the newest installed copy of its MCP server.
// Safe to delete: the control panel writes it again.
const fs = require('node:fs');
const path = require('node:path');
const DIR = ${JSON.stringify(extensionsDir)};
const FALLBACK = ${JSON.stringify(fallback)};
const PATTERN = /^${PREFIX.replaceAll('.', '\\.')}(\\d+)\\.(\\d+)\\.(\\d+)$/;
const newer = (a, b) => { for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] > b[i]; return false; };
let entry = FALLBACK, best;
try {
  for (const name of fs.readdirSync(DIR)) {
    const match = PATTERN.exec(name);
    const file = path.join(DIR, name, 'src/fast-context/server.cjs');
    if (!match || !fs.existsSync(file)) continue;
    const version = match.slice(1).map(Number);
    if (!best || newer(version, best)) { best = version; entry = file; }
  }
} catch {}
// The user switch lives next to this file.
process.env.FUSION_BYOK_STORAGE_DIR = __dirname;
const server = require(entry);
if (typeof server.main === 'function') server.main(process.argv.slice(2));
else {
  const child = require('node:child_process').spawn(process.execPath, [entry, ...process.argv.slice(2)], { stdio: 'inherit' });
  child.on('exit', code => { process.exitCode = code ?? 1; });
}
`;
}

// Writes the launcher only when its content changed. Returns its absolute path.
function ensureLauncher({ storageDir, extensionPath }) {
  if (!path.isAbsolute(storageDir) || !path.isAbsolute(extensionPath)) throw new Error('absolute_paths_required');
  const file = path.join(storageDir, FILE);
  const source = launcherSource({ extensionsDir: path.dirname(extensionPath),
    fallback: path.join(extensionPath, 'src/fast-context/server.cjs') });
  let current;
  try { current = fs.readFileSync(file, 'utf8'); } catch {}
  if (current !== source) {
    fs.mkdirSync(storageDir, { recursive: true });
    const temp = file + '.' + process.pid + '.tmp';
    fs.writeFileSync(temp, source, { mode: 0o644 });
    fs.renameSync(temp, file);
  }
  return file;
}

module.exports = { launcherSource, ensureLauncher, FILE };
